UPDATE sys_user_role
SET deleted = 1
WHERE user_id = #{userId}

mapper.select:
WITH RECURSIVE dept_tree AS ( SELECT id, name, parent_id FROM sys_department WHERE id = #{deptId} AND deleted = 0 UNION ALL SELECT d.id, d.name, d.parent_id FROM sys_department d INNER JOIN dept_tree dt ON d.parent_id = dt.id WHERE d.deleted = 0 ) SELECT u.id, u.tenant_id, u.username, u.password, u.real_name, u.email, u.phone, u.avatar, u.enabled, u.create_time, u.update_time, u.deleted FROM sys_user u INNER JOIN sys_user_department ud ON u.id = ud.user_id AND ud.deleted = 0 INNER JOIN dept_tree dt ON ud.department_id = dt.id WHERE u.deleted = 0
AND dt.id = #{deptId}
AND dt.id != #{deptId}
